package main

import (
	"fmt"
	"net"
	"strings"
)

func getTargetForRedirect(target string, domain string) string {
	if target == "" {
		return "https://" + domain
	}

	// Parse target URL
	targetURL, err := net.ParseURL(target)
	if err != nil {
		return "https://" + domain
	}

	// Parse domain URL
	domainURL, err := net.ParseURL("https://" + domain)
	if err != nil {
		return "https://" + domain
	}

	// Check if target domain is a subdomain of the provided domain
	targetHost := targetURL.Host
	domainHost := domainURL.Host

	if strings.HasSuffix(targetHost, domainHost) && strings.Count(targetHost, ".") > strings.Count(domainHost, ".") {
		return target
	}

	return "https://" + domain
}

func main() {
	fmt.Println(getTargetForRedirect("https://music.example.com", "example.com")) // "https://music.example.com"
	fmt.Println(getTargetForRedirect("https://example.com/service", "example.com")) // "https://example.com/service"
	fmt.Println(getTargetForRedirect("https://blog.example.com/posts", "example.com")) // "https://blog.example.com/posts"
	fmt.Println(getTargetForRedirect("https://another.com", "example.com")) // "https://example.com"
}
